mapper.select:
SELECT '可用余额' AS name, IFNULL(SUM(available_balance), 0) AS value FROM bank_account WHERE user_id = #{userId}
UNION ALL
SELECT '冻结金额' AS name, IFNULL(SUM(frozen_balance), 0) AS value FROM bank_account WHERE user_id = #{userId}
UNION ALL
SELECT '待还借款' AS name, IFNULL(SUM(t.amount + t.accumulated_interest), 0) AS value FROM bank_transaction_log t INNER JOIN bank_account a ON t.account_id = a.card_number WHERE a.user_id = #{userId} AND t.transaction_type = 1 AND t.status = 0
